using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;

// Run in a disposable project with Original/Fixed model pairs and the meter
// fixtures generated by FbxScaleTests. Uses Unity's default file-unit conversion.
public static class FbxScaleValidation
{
    [Serializable] public sealed class Measurement
    {
        public string path;
        public float fileScale;
        public Vector3 size;
        public int meshes, bones;
        public float translationMeters;
    }
    [Serializable] public sealed class Report
    {
        public bool success;
        public string error;
        public List<Measurement> models = new List<Measurement>();
    }

    private static Measurement Measure(string path, bool sample = false)
    {
        var importer = (ModelImporter)AssetImporter.GetAtPath(path);
        importer.globalScale = 1;
        importer.useFileScale = true;
        importer.animationType = ModelImporterAnimationType.Generic;
        importer.preserveHierarchy = false;
        importer.SaveAndReimport();
        var source = AssetDatabase.LoadAssetAtPath<GameObject>(path);
        var instance = UnityEngine.Object.Instantiate(source);
        try
        {
            var renderers = instance.GetComponentsInChildren<Renderer>(true);
            var bounds = renderers[0].bounds;
            foreach (var renderer in renderers.Skip(1)) bounds.Encapsulate(renderer.bounds);
            var result = new Measurement { path = path, fileScale = importer.fileScale, size = bounds.size,
                meshes = renderers.Length, bones = instance.GetComponentsInChildren<SkinnedMeshRenderer>(true)
                    .SelectMany(r => r.bones).Distinct().Count() };
            if (sample)
            {
                var clip = AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>()
                    .First(c => !c.name.StartsWith("__preview__"));
                var bone = instance.GetComponentsInChildren<Transform>(true).Single(t => t.name == "Bip001");
                clip.SampleAnimation(instance, 0);
                var start = bone.position;
                clip.SampleAnimation(instance, 1);
                result.translationMeters = Vector3.Distance(start, bone.position);
            }
            return result;
        }
        finally { UnityEngine.Object.DestroyImmediate(instance); }
    }

    public static void Run()
    {
        var args = Environment.GetCommandLineArgs();
        var reportPath = args[Array.IndexOf(args, "-testReport") + 1];
        var report = new Report();
        try
        {
            foreach (var name in new[] { "Anbi", "Claymore" })
            {
                var old = Measure("Assets/Original/" + name + ".fbx");
                var fixedModel = Measure("Assets/Fixed/" + name + ".fbx");
                report.models.Add(old); report.models.Add(fixedModel);
                if ((fixedModel.size - old.size * 100).magnitude > 0.001f ||
                    old.meshes != fixedModel.meshes || old.bones != fixedModel.bones)
                    throw new Exception(name + " does not retain mesh/skin structure at corrected meter size");
            }
            foreach (var multiplier in new[] { 0.01f, 1f, 2f })
            {
                var model = Measure("Assets/Fixtures/meter-scale-" + multiplier.ToString(System.Globalization.CultureInfo.InvariantCulture) + "-True.fbx", true);
                report.models.Add(model);
                if (Math.Abs(model.size.x - multiplier) > 0.0001f ||
                    Math.Abs(model.size.y - multiplier) > 0.0001f ||
                    Math.Abs(model.translationMeters - multiplier) > 0.0001f)
                    throw new Exception("Mesh and animation are not in the expected meter units: " + multiplier);
            }
            report.success = true;
        }
        catch (Exception ex) { report.error = ex.ToString(); }
        File.WriteAllText(reportPath, JsonUtility.ToJson(report, true));
        if (!report.success) throw new Exception(report.error);
    }
}
